const linhas = $input.all().map(i => i.json);
if (!linhas.length) throw new Error('Consulta sem metadados.');
if (linhas[0].erro_consulta) throw new Error(linhas[0].erro_consulta);
const competencia = linhas[0].competencia_solicitada;
const atual = $now.setZone('America/Sao_Paulo').toFormat('yyyy-MM');
const unidades = linhas.filter(r => r.unidade_codigo != null).map(r => {
  const { competencia_solicitada, erro_consulta, payload_alunos, payload_contratos, payload_acessos, ...dados } = r;
  return dados;
});
return [{json:{sucesso:true,competencia,ao_vivo:competencia===atual,fonte:'pacto_mcp',gerado_em:$now.toUTC().toISO(),total_unidades:unidades.length,unidades}}];
